import sys
import os
import subprocess
import json

def main():
    if len(sys.argv) != 2:
        print("Usage: python cmd_cache.py <cache_path>", file=sys.stderr)
        sys.exit(1)

    cache_path = sys.argv[1]
    cache = {}

    # Load cache if it exists
    if os.path.exists(cache_path):
        try:
            with open(cache_path, 'r') as f:
                cache = json.load(f)
        except (json.JSONDecodeError, IOError):
            pass  # Start with empty cache if file is corrupted

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        if line in cache:
            # Output cached result
            print(cache[line]['output'], end='')
            print(cache[line]['status'], file=sys.stderr)
        else:
            # Execute command
            try:
                result = subprocess.run(line, shell=True, check=True,
                                       stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                       text=True)
                output = result.stdout
                status = result.returncode
                cache[line] = {'output': output, 'status': status}
                print(output, end='')
                print(status, file=sys.stderr)
            except subprocess.CalledProcessError as e:
                output = e.stdout
                status = e.returncode
                cache[line] = {'output': output, 'status': status}
                print(output, end='')
                print(status, file=sys.stderr)

    # Save cache
    with open(cache_path, 'w') as f:
        json.dump(cache, f)

if __name__ == "__main__":
    main()

