#!/usr/bin/env python3
import sys
import os
import subprocess
import pickle

def main():
    if len(sys.argv) != 2:
        print("Usage: python cmd_cache.py <cache_path>", file=sys.stderr)
        sys.exit(1)

    cache_path = sys.argv[1]
    cache = {}

    if os.path.exists(cache_path):
        try:
            with open(cache_path, 'rb') as f:
                cache = pickle.load(f)
        except (pickle.PickleError, EOFError):
            pass  # Empty cache if file is corrupted or empty

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        if line in cache:
            stdout, exit_status = cache[line]
            print(stdout, end='')
            print(f"{exit_status}", file=sys.stderr)
        else:
            try:
                result = subprocess.run(line, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                stdout = result.stdout
                exit_status = result.returncode
                print(stdout, end='')
                print(f"{exit_status}", file=sys.stderr)
                cache[line] = (stdout, exit_status)
            except subprocess.CalledProcessError as e:
                stdout = e.stdout
                exit_status = e.returncode
                print(stdout, end='')
                print(f"{exit_status}", file=sys.stderr)
                cache[line] = (stdout, exit_status)

    with open(cache_path, 'wb') as f:
        pickle.dump(cache, f)

if __name__ == "__main__":
    main()
